price\": 50}, {\"name\": \"日租\", \"price\": 20}]','2026-06-03 09:45:16','2026-06-03 09:45:16'),(93,141,'3','[{\"name\": \"月租\", \"price\": 30}, {\"name\": \"半月\", \"price\": 20}, {\"name\": \"一周\", \"price\": 10}, {\"name\": \"日租\", \"price\": 5}]','2026-06-03 09:51:23','2026-06-03 09:51:23'),(102,142,'时间','[{\"name\": \"A套餐\", \"price\": 288}, {\"name\": \"B套餐\", \"price\": 588}, {\"name\": \"C套餐\", \"price\": 888}]','2026-06-03 10:07:30','2026-06-03 10:07:30'),(103,150,'时间','[{\"name\": \"一周\", \"price\": 0}]','2026-06-05 17:57:19','2026-06-05 17:57:19'),(104,148,'时间','[{\"name\": \"一个月\", \"price\": 0}]','2026-06-05 17:57:59','2026-06-05 17:57:59'),(105,149,'时间','[{\"name\": \"一个月\", \"price\": 0}]','2026-06-05 17:58:22','2026-06-05 17:58:22'),(106,147,'时间','[{\"name\": \"一个月\", \"price\": 0}]','2026-06-05 17:58:38','2026-06-05 17:58:38');
