--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint unsigned NOT NULL,
  `category_id` bigint unsigned DEFAULT NULL,
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `images` json DEFAULT NULL,
  `price` decimal(10,2) NOT NULL,
  `original_price` decimal(10,2) DEFAULT NULL,
  `stock` int unsigned NOT NULL DEFAULT '0',
  `unit` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '份',
  `sales` int unsigned NOT NULL DEFAULT '0',
  `sort` int unsigned NOT NULL DEFAULT '0',
  `status` tinyint unsigned NOT NULL DEFAULT '1',
  `deleted_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_products_category_id` (`category_id`),
  KEY `idx_products_merchant_id` (`merchant_id`),
  KEY `idx_products_sales` (`merchant_id`,`sales`),
  KEY `idx_products_sort` (`merchant_id`,`sort`),
  KEY `idx_products_status` (`status`),
  CONSTRAINT `fk_products_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_products_merchant` FOREIGN KEY (`merchant_id`) REFERENCES `merchants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=151 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='商品表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `products`
--

LOCK TABLES `products` WRITE;
/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (5,1,7,'一字扶手','\"1、外管材质：ABS材质，直径35mm；\n2、内管材质：不锈钢直径25mm\n3、扶手表面使用环保标准、抗老化、耐腐蚀材料，能有效抑制大肠杆菌、金黄色葡萄球菌等细菌；扶手表面采用防滑浮点设计，厚度为0.5毫米。\n盖外尺寸：600MM\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780032502633.png\"]',36.00,68.00,100,'份',1,0,1,NULL,'2026-05-29 13:29:26','2026-06-02 13:56:26'),(6,1,7,'L型扶手','\"1、外管材质：ABS材质，直径35mm；\n2、内管材质：不锈钢，直径25mm\n3、扶手表面使用环保标准、抗老化、耐腐蚀材料，能有效抑制大肠杆菌、金黄色葡萄球菌等细菌；扶手表面采用防滑浮点设计，厚度为0.5毫米。\n盖外尺寸：600*400MM\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780032627448.png\"]',74.00,99.00,10,'份',0,0,1,NULL,'2026-05-29 13:30:44','2026-05-29 14:36:05'),(7,1,7,'马桶扶手','\"1、外管材质：ABS材质，直径35mm；\n2、内管材质：不锈钢，直径25mm\n3、扶手表面使用环保标准、抗老化、耐腐蚀材料，能有效抑制大肠杆菌、金黄色葡萄球菌等细菌；扶手表面采用防滑浮点设计，厚度为0.5毫米。\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780034010146.png\"]',80.00,110.00,10,'份',0,0,1,NULL,'2026-05-29 13:32:20','2026-05-29 14:35:54'),(8,1,9,'淋浴凳','\"1、外管材质：ABS材质，直径35mm；\n2、内管材质：不锈钢/镀锌内管，直径25mm\n3、扶手表面使用环保标准、抗老化、耐腐蚀材料，能有效抑制大肠杆菌、金黄色葡萄球菌等细菌；扶手表面采用防滑浮点设计，厚度为0.5毫米。\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780032792752.png\"]',290.00,350.00,10,'份',0,0,2,NULL,'2026-05-29 13:33:23','2026-05-29 14:33:11'),(9,1,10,'助行器-双弯铝合金/带白板不带轮','品名；铝合金助行器 带轮子可两用                             壁厚；1.2                                        尺寸；49*49*74CM(长宽高)                         材质；铝合金环保负离子喷粉                          称重；200斤以上                                   适用场合；家用 老年公寓 疗养院 医院','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780032902030.png\"]',210.00,260.00,10,'份',0,0,2,NULL,'2026-05-29 13:35:20','2026-05-29 14:33:00'),(10,1,6,'助行器-铝合金-带便盆带盖/不带轮','\"品名；铝合金助行器带便盆款（一箱6个）\n尺寸：49*49*74CM(长宽高)   管壁厚：1.2 mm                                    材质：铝合金环保负离子喷粉        \n承重：200斤以上\n适用场合：家用 老年公寓 疗养院 医院\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780032958747.png\"]',270.00,310.00,10,'份',0,0,2,NULL,'2026-05-29 13:38:05','2026-05-29 14:25:45'),(11,1,9,'坐便凳折叠款-碳钢','\"产品品牌； 伟誉\n座椅高度； 34-44cm\n产品型号；坐便椅(碳钢喷涂)                      \n座椅总高度；57-67cm\n产品尺； (66x76)x40x53cm\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780033129228.png\"]',180.00,210.00,10,'份',0,0,2,NULL,'2026-05-29 13:39:18','2026-05-29 14:32:44'),(12,1,9,'便盆款淋浴椅','、功能：洗澡坐便两用。材质：底板及背板优质PE材料，主架1.0mm加厚铝合金管，防滑橡胶脚垫，高密度泡棉扶手。坐垫开孔处理更好的防水积水，抗菌尼龙面板，掀盖设计，方便提桶，烤漆太空铝防滑坐板，表面纹路处理，坐姿舒适镂空透气漏水气孔。高度任意调节。2、承重：200kg底板干爽，龟裂防滑纹理，带漏水透气。加厚软质扶手，泡沫软扶手柔软舒适，久握方便加厚防滑防水纹理靠背，靠背上带有便携提口，铝合金表面喷砂处理，外观高端，不生锈可随意轻松移动。3、扶手/靠背可拆卸满足不同需求，舒适方便吸盘大脚垫，防滑大脚垫大大吸住地面即使在浴室也纹丝不动，脚垫内置铁片耐磨。','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780033198049.png\"]',140.00,180.00,10,'份',0,0,2,NULL,'2026-05-29 13:40:28','2026-05-29 14:32:33'),(13,1,11,'铝合金四爪带灯拐        （滚花设计拐身）','\"铝合金四爪带灯拐杖\n铝材厚度：1.2mm，直径19cm，调节高度68-90.5cm\n精美滚花设计拐身，管壁采用加厚优质铝合金材质，承重力强，，ABS防滑带灯把手,LED设计配用两节五号电池，方便照明，弹珠式10档调节高度（身高范围145-190cm）），下部横向防滑顶丝锁定，底部防滑脚垫，使用更加稳固。（发货不带电池）\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780033266951.png\"]',90.00,130.00,0,'份',0,0,2,NULL,'2026-05-29 13:41:36','2026-05-29 14:32:20'),(14,1,11,'可折叠坐拐铝管古铜','\"完全展开尺寸 400*520*670-760mm（人工测量稍有误差）\n壁厚 1.2mm   直径22mm\n坐板尺寸：24*20\n脚管五档可调节，使用方便；同时可从拐杖状态转换为坐凳状态，用途广泛。\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780033332741.png\"]',110.00,150.00,10,'份',0,0,2,NULL,'2026-05-29 13:42:32','2026-05-29 14:32:10'),(15,1,12,'轮椅-普通黑色、银色','\"（1）规格 张车尺寸：92cm*68cm*102cm\n（2）轮椅承载重量90kg;\n（3）各部位尺寸：扶手高71cm,坐高50cm,座宽45cm，座深42cm,收车宽27cm;\n（4）轮子采用的是实心前后轮，后轮24寸、前轮7寸、简单无需养护耐磨性强，平整路面室内外均可;\n（5）脚踏板防滑加厚，可以调节高度，更多的适用各类人群;\n（6）前轮360°旋转方向双轴承，转动灵活;\n（7）轮椅配备可调节式安全带，保证使用者的安全;\n（8）轮椅座垫采用600D牛津布内夹加厚帆布与海绵缝纫制成，车架材质采用优质钢管，管直径22mm、壁厚1.0mm，整体焊接一体成型，表面喷涂处理，美观、坚固耐用。前后四刹车设计，行驶中更加有保障。加宽挡腿带，加强支撑腿部，具有折叠功能，节省空间。\"','[\"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780033400761.png\", \"https://lexiang-oss.jxxme.cn/uploads/merchant/1/1780033404944.png\"]',480.00,550.00,10,'份',0,0,2,NULL,'2026-05-29 13:43:53','2026-05-29 14:31:54'),(16,1,9,'黑色/带便盆','\"1）规格 张车尺寸：92cm*68cm*102cm\n（2）轮椅承载重量90kg;\n（3）各部位尺寸：扶手高71cm,坐高50cm,座宽45cm，座深42cm,收车宽27cm;\n（4）坐板内置加厚海绵，久坐不累乘坐更